    [NonSerialized] readonly Dictionary<int,Material> referenceMaterials=new Dictionary<int,Material>();
    sealed class WindowProbe { public Transform owner;public Vector3 point,direction;public float clearDistance=5; }
    [Serializable] public sealed class Bundle { public int schemaVersion; public Floor[] floors; public Roof[] roofs; public Envelope envelope; public float northSiteShiftX; public SouthEntrance southEntrance; public Architecture architecture; }
