    [MenuItem("Tools/Engineering Building/Building Generator")]
    static void Open(){var window=GetWindow<EngineeringFloor1Generator>("Building 9 v6.7");window.minSize=new Vector2(660,450);}
    void OnEnable()
    {
        EditorApplication.playModeStateChanged-=OnPlayModeStateChanged;
        EditorApplication.playModeStateChanged+=OnPlayModeStateChanged;
        runtimePlans=null;
        meshBuildFolder=null;windowProbes.Clear();
        working=false;queuedOperation=0;lastBuildError="";buildStage="Ready";referenceMaterials.Clear();
        // Recover newly added settings if an older saved window restores zeros.
        if(towerWindowSill<=0||towerWindowHeight<=0){towerWindowSill=2.35f;towerWindowHeight=1.10f;}
        if(wingWindowSill<=0||wingWindowHeight<=0){wingWindowSill=.95f;wingWindowHeight=2.05f;}
        if(roofSettingsVersion<1)
        {roofSlabDepth=.22f;roofParapetHeight=.60f;penthouseServiceRise=.60f;roofsVisible=true;roofSettingsVersion=1;}
        if(southEntranceSettingsVersion<2)
        {includePicnicSeating=true;picnicTableCount=2;southEntranceSettingsVersion=2;}
        status="v6.7: piano glazing, breezeway vending, S2 landing, aligned S3 stair opening and HVAC access. Visibility controls are safe in Play Mode.";
        titleContent=new GUIContent("Building 9 v6.7");
        minSize=new Vector2(660,450);
        try {buildStage="loading embedded plans";Data(true);buildStage="Ready";}
        catch(ExitGUIException){throw;}
        catch(Exception error){ReportFailure(error);}
    }
    void OnDisable()
    {
        EditorApplication.delayCall-=RunQueuedOperation;
        EditorApplication.playModeStateChanged-=OnPlayModeStateChanged;
        queuedOperation=0;working=false;
    }
    static bool IsPlaySession
    {get{return EditorApplication.isPlaying||EditorApplication.isPlayingOrWillChangePlaymode;}}
    void OnPlayModeStateChanged(PlayModeStateChange state)
    {
        if(state==PlayModeStateChange.ExitingEditMode||state==PlayModeStateChange.EnteredPlayMode)
        {EditorApplication.delayCall-=RunQueuedOperation;queuedOperation=0;}
        Repaint();
    }
    static void RecordSceneChange(UnityEngine.Object target,string action)
    {if(target!=null&&!IsPlaySession)Undo.RecordObject(target,action);}
