        EditorGUILayout.LabelField("Building 9 | v6.7 | Floors 1--6",EditorStyles.boldLabel);
        EditorGUILayout.HelpBox(status,string.IsNullOrEmpty(lastBuildError)?MessageType.Info:MessageType.Error);
        using(new EditorGUI.DisabledScope(string.IsNullOrEmpty(lastBuildError)))
            if(GUILayout.Button("Copy last build error"))EditorGUIUtility.systemCopyBuffer=lastBuildError;
        int present=0;for(int n=1;n<=FloorCount;n++)if(FloorRoot(n)!=null)present++;
        EditorGUILayout.LabelField("Scene: "+present+" / "+FloorCount+" floors. Floor and roof controls enable after those objects are generated.",EditorStyles.wordWrappedMiniLabel);
        if(IsPlaySession)EditorGUILayout.HelpBox("Play Mode: visibility changes are temporary. Stop Play Mode to generate, replace or despawn the building.",MessageType.Info);
        using(var viewport=new EditorGUILayout.ScrollViewScope(scroll))
        {
        scroll=viewport.scrollPosition;
        floorHeight=EditorGUILayout.FloatField("Storey height (assumed, m)",floorHeight);
        floorSlabDepth=EditorGUILayout.FloatField("Slab depth (assumed, m)",floorSlabDepth);
        openingHeadHeight=EditorGUILayout.FloatField("Door head height (assumed, m)",openingHeadHeight);
        buildingScale=EditorGUILayout.FloatField("Whole-building scale",buildingScale);
        roomLabels=EditorGUILayout.Toggle("Room labels on highest shown floor",roomLabels);
        includeSite=EditorGUILayout.Toggle("Raised north ground and paths",includeSite);
        colliders=EditorGUILayout.Toggle("Generate geometry colliders",colliders);
        EditorGUILayout.Space();EditorGUILayout.LabelField("First-floor breezeway",EditorStyles.boldLabel);
        includePicnicSeating=EditorGUILayout.Toggle("Round tables and benches",includePicnicSeating);
        picnicTableCount=EditorGUILayout.IntSlider("Table and bench sets",picnicTableCount,2,4);
        EditorGUILayout.HelpBox("Two neighbouring table/bench sets occupy the recessed corner beside Room 167. Optional extra sets stay clear of the entrances. Furniture dimensions are estimates.",MessageType.None);
        EditorGUILayout.Space();
        EditorGUILayout.LabelField("Window elevations - estimated from reference photos",EditorStyles.boldLabel);
        towerWindowSill=EditorGUILayout.FloatField("Tower sill above floor (m)",towerWindowSill);
        towerWindowHeight=EditorGUILayout.FloatField("Tower glazing height (m)",towerWindowHeight);
        wingWindowSill=EditorGUILayout.FloatField("Two-storey wing sill (m)",wingWindowSill);
        wingWindowHeight=EditorGUILayout.FloatField("Two-storey wing glazing height (m)",wingWindowHeight);
        if(GUILayout.Button("Reset window heights to photo estimates"))
        {towerWindowSill=2.35f;towerWindowHeight=1.10f;wingWindowSill=.95f;wingWindowHeight=2.05f;}
        EditorGUILayout.HelpBox("East / meadow and west / Olive Lane window bays follow the photographed elevations. " +
            "The tower has high horizontal glazing above solid panels; the two-storey wing has taller glazing above brick-coloured panels. " +
            "Window heights are estimates and can be adjusted here. Doors, rooms and reference sheets share the same constrained registration. " +
            "Floor 1 S5 still follows the perpendicular drawn flights; verify that physical route on site.",MessageType.None);
        EditorGUILayout.HelpBox("v6.7 adds glazing around the piano bay, two generic vending machines beside the S3 exit, a floor over the unused S2 opening, an aligned S3 slab opening, and HVAC access through service room 212. All stair flights and existing room layouts are retained. Furniture dimensions are estimates.",MessageType.None);
        roofSlabDepth=EditorGUILayout.FloatField("Roof slab depth (assumed, m)",roofSlabDepth);
        roofParapetHeight=EditorGUILayout.FloatField("Tower parapet height (assumed, m)",roofParapetHeight);
        penthouseServiceRise=EditorGUILayout.FloatField("603B service steps rise (assumed, m)",penthouseServiceRise);
        using(new EditorGUI.DisabledScope(working||queuedOperation!=0||IsPlaySession))
        {
            // Importing assets and replacing scene objects must not run inside
            // an IMGUI layout pass. Queue both actions after inspectors update.
            if(GUILayout.Button("Generate / Replace Complete Building",GUILayout.Height(32)))QueueOperation(1);
            if(GUILayout.Button("Validate embedded plans"))QueueOperation(2);
        }
        EditorGUILayout.Space();
        using(new EditorGUILayout.HorizontalScope())
        {
            if(GUILayout.Button("All floors"))Preset(0);
            for(int f=1;f<=FloorCount;f++)if(GUILayout.Button("Only "+f))Preset(f);
        }
        for(int f=1;f<=FloorCount;f++)DrawFloor(f);
        DrawRoofs();
        DrawSite();
        EditorGUILayout.HelpBox("Active disables the group and colliders. Render changes visibility. Reference is an inspection sheet with no collider. " +
            "Stair connections are separate, so floor-only inspection can include arrivals from below. Hiding floors does not move them. Regeneration replaces the generated root and is undoable.",MessageType.None);
        }
        SyncLabels();
    }
    void QueueOperation(int operation)
    {
        if(working||queuedOperation!=0)return;
        if(IsPlaySession){status="Stop Play Mode before generating or despawning scene objects.";Repaint();return;}
        queuedOperation=operation;lastBuildError="";
        status=operation==1?"Generation queued. Preparing all six floors and roofs...":
            (operation==2?"Plan validation queued...":"Floor despawn queued...");
        EditorApplication.delayCall-=RunQueuedOperation;
        EditorApplication.delayCall+=RunQueuedOperation;
        Repaint();
    }
    void RunQueuedOperation()
    {
        if(this==null||queuedOperation==0)return;
        if(EditorApplication.isCompiling||EditorApplication.isUpdating)
        {EditorApplication.delayCall+=RunQueuedOperation;return;}
        if(IsPlaySession)
        {queuedOperation=0;status="Exit Play mode before generating the building.";Repaint();return;}
        int operation=queuedOperation;queuedOperation=0;working=true;
        try
        {
            if(operation==1)Generate();else if(operation==2)ValidateOnly();
            else if(operation>100&&operation<=100+FloorCount)DespawnFloor(operation-100);
        }
        finally {working=false;Repaint();}
    }
    void ReportFailure(Exception error)
    {
        lastBuildError="Stage: "+buildStage+"\n"+error;
        status="Build stopped at "+buildStage+": "+error.GetType().Name+" - "+error.Message;
        Debug.LogError("Building 9 v6.7\n"+lastBuildError);
        Repaint();
    }
    void Clamp()
    {
        floorHeight=Mathf.Clamp(floorHeight,3f,6f);floorSlabDepth=Mathf.Clamp(floorSlabDepth,.1f,.4f);
        // Reserve the minimum service landing rise plus a solid lintel above it.
        openingHeadHeight=Mathf.Clamp(openingHeadHeight,1.9f,floorHeight-floorSlabDepth-.35f);buildingScale=Mathf.Clamp(buildingScale,.05f,20f);
        float ceiling=floorHeight-floorSlabDepth;
        towerWindowSill=Mathf.Clamp(towerWindowSill,.4f,ceiling-.65f);
        towerWindowHeight=Mathf.Clamp(towerWindowHeight,.35f,ceiling-towerWindowSill-.18f);
        wingWindowSill=Mathf.Clamp(wingWindowSill,.4f,ceiling-.65f);
        wingWindowHeight=Mathf.Clamp(wingWindowHeight,.35f,ceiling-wingWindowSill-.18f);
        roofSlabDepth=Mathf.Clamp(roofSlabDepth,floorSlabDepth,.6f);
        roofParapetHeight=Mathf.Clamp(roofParapetHeight,.15f,1.3f);
        penthouseServiceRise=Mathf.Clamp(penthouseServiceRise,.25f,Mathf.Min(.85f,ceiling-openingHeadHeight-.1f));
        picnicTableCount=Mathf.Clamp(picnicTableCount,2,4);
    }
    static bool HasSixFloorPlans(Bundle plans)
    {
        if(plans==null||plans.schemaVersion!=67||plans.floors==null||plans.floors.Length!=FloorCount||plans.roofs==null||plans.roofs.Length<3)return false;
        if(plans.architecture==null||plans.architecture.portals==null||plans.architecture.seams==null)return false;
        if(plans.southEntrance==null||plans.southEntrance.paving==null||plans.southEntrance.paving.t==null||
            plans.southEntrance.approach==null||plans.southEntrance.approach.t==null)return false;
        for(int f=0;f<FloorCount;f++)
        {
            Floor floor=plans.floors[f];
            if(floor==null||floor.number!=f+1||floor.slab==null||floor.slab.v==null||floor.slab.t==null||
                floor.walls==null||floor.finishes==null||floor.headers==null||floor.labels==null||
                floor.flights==null||floor.landings==null||floor.doors==null||floor.facades==null)return false;
        }
        return true;
    }
    Bundle Data(bool reload=false)
    {
        if(reload)runtimePlans=null;
        if(HasSixFloorPlans(runtimePlans))return runtimePlans;
        runtimePlans=null;
        byte[] bytes=Convert.FromBase64String(EmbeddedData);
        string json;
        using(var input=new MemoryStream(bytes))using(var zipped=new GZipStream(input,CompressionMode.Decompress))using(var reader=new StreamReader(zipped))
            json=reader.ReadToEnd();
        Bundle loaded=JsonUtility.FromJson<Bundle>(json);
        NormalizeOptionalFields(loaded);
        if(!HasSixFloorPlans(loaded))
        {
            int count=loaded!=null&&loaded.floors!=null?loaded.floors.Length:0;
            throw new InvalidOperationException("v6.7 embedded-plan decode failed: read "+count+
                " floor records from "+json.Length+" JSON characters; expected complete Floors 1--6. "+
                "Close and reopen this generator window and ensure only one copy of EngineeringFloor1Generator.cs is installed.");
        }
        runtimePlans=loaded;
        return runtimePlans;
    }
    static Shape EmptyShape()
    {return new Shape{v=new float[0],t=new int[0],rings=new Ring[0]};}
    static void NormalizeOptionalFields(Bundle plans)
    {
        if(plans==null||plans.floors==null)return;
        if(plans.southEntrance!=null)
        {
            if(plans.southEntrance.vendingMachines==null)plans.southEntrance.vendingMachines=new VendingMachine[0];
            if(plans.southEntrance.vendingPad==null||plans.southEntrance.vendingPad.t==null)plans.southEntrance.vendingPad=EmptyShape();
        }
        foreach(Floor floor in plans.floors)
        {
            if(floor==null)continue;
            if(floor.wellGuards==null)floor.wellGuards=new WellGuard[0];
            // Some Unity serializers create an empty inline Shape for a missing
            // optional object. Non-null therefore does not imply valid arrays.
            if(floor.serviceDeck==null||floor.serviceDeck.v==null||floor.serviceDeck.t==null||floor.serviceDeck.rings==null)
                floor.serviceDeck=EmptyShape();
            if(floor.serviceFlights==null)floor.serviceFlights=new Flight[0];
            if(floor.serviceHeaders==null)floor.serviceHeaders=new Shape[0];
            if(floor.serviceGuard==null)floor.serviceGuard=new float[0];
            if(floor.entryHeader==null||floor.entryHeader.v==null||floor.entryHeader.t==null||floor.entryHeader.rings==null)
                floor.entryHeader=EmptyShape();
            if(floor.entryWindows==null)floor.entryWindows=new EntryWindow[0];
        }
    }
    void ValidateData()
    {
        // Generation and validation always decode the embedded source afresh.
        // Never accept a Bundle resurrected from an older EditorWindow session.
        Bundle b=Data(true);
        for(int f=0;f<FloorCount;f++)
        {
            Floor floor=b.floors[f];if(floor.number!=f+1)throw new InvalidOperationException("Floor numbering is invalid.");
            CheckShape(floor.slab);CheckShape(floor.entryHeader);
            foreach(EntryWindow window in floor.entryWindows)
                if(window.width<.18f||string.IsNullOrEmpty(window.name))
                    throw new InvalidOperationException("Invalid entrance window on Floor "+floor.number);
            foreach(WallPart w in floor.walls)CheckShape(w.mesh);
            foreach(Finish finish in floor.finishes)CheckShape(finish.mesh);
            foreach(Facade facade in floor.facades)
            {
                if(facade.posts==null||facade.posts.Length<2||facade.depth<.1f||facade.postWidth<=0||Mathf.Abs(facade.normal)!=1f)
                    throw new InvalidOperationException("Invalid exterior window bay on Floor "+floor.number);
                for(int j=1;j<facade.posts.Length;j++)if(facade.posts[j]-facade.posts[j-1]<=facade.postWidth+.1f)
                    throw new InvalidOperationException("An exterior window bay has no clear width.");
            }
            if(floor.number>1 && floor.flights.Any(fl=>fl.name.StartsWith("S3")))throw new InvalidOperationException("S3 must terminate at Floor 2.");
            foreach(Shape header in floor.headers)CheckShape(header);
            foreach(Landing landing in floor.landings)CheckShape(landing.mesh);
            if(floor.exterior!=null&&floor.exterior.count>0)
            {
                Exterior e=floor.exterior;CheckShape(e.porch);CheckShape(e.apron);CheckShape(e.ground);CheckShape(e.header);
                if(e.count!=3||e.drop<=0||e.landingHeight<=0||Mathf.Abs(e.landingHeight-e.drop)>.0001f||e.width<1||e.railHeight<.8f)
                    throw new InvalidOperationException("S3 requires a raised porch, three steps and continuous side railings.");
            }
            CheckShape(floor.refMesh);
            if(floor.refUV==null||floor.refUV.Length!=floor.refMesh.v.Length)
                throw new InvalidOperationException("Floor "+floor.number+" reference UV registration is invalid.");
        }
        if(b.floors[0].entryWindows.Length!=5||b.floors[0].entryWindows.Count(w=>w.cross)!=4)
            throw new InvalidOperationException("The east entrance must have four crossed windows and one narrow sidelight.");
        CheckCommonFrame(b);
        CheckShape(b.southEntrance.paving);CheckShape(b.southEntrance.approach);CheckShape(b.southEntrance.vendingPad);
        if(b.southEntrance.vendingMachines.Length!=2||b.southEntrance.vendingPad.t.Length==0)
            throw new InvalidOperationException("The two breezeway vending machines and their pad are missing.");
        if(b.floors[1].entryWindows.Length!=3||!b.floors[1].doors.Any(d=>d.name=="HVAC service door via 212"))
            throw new InvalidOperationException("The piano glazing or HVAC service entrance is missing.");
        if(b.southEntrance.tables==null||b.southEntrance.tables.Length!=4)
            throw new InvalidOperationException("The breezeway corner seating layout is incomplete.");
        if(!b.floors[0].doors.Any(d=>d.name=="South wing breezeway glass double doors")||
            !b.floors[0].doors.Any(d=>d.name=="Tower breezeway glass double doors"))
            throw new InvalidOperationException("Both breezeway glass entrances must be retained.");
        if(b.architecture.expectedLabels==null||b.architecture.expectedLabels.Length!=FloorCount||
            b.architecture.expectedFlights==null||b.architecture.expectedFlights.Length!=FloorCount)
            throw new InvalidOperationException("The feature-preservation checks are missing.");
        for(int i=0;i<FloorCount;i++)
            if(b.floors[i].labels.Length!=b.architecture.expectedLabels[i]||b.floors[i].flights.Length!=b.architecture.expectedFlights[i])
                throw new InvalidOperationException("A room label or stair flight is missing on Floor "+(i+1));
        foreach(Roof roof in b.roofs)
        {
            if(roof.aboveFloor<1||roof.aboveFloor>FloorCount)throw new InvalidOperationException("A roof has an invalid elevation.");
            CheckShape(roof.slab);CheckShape(roof.membrane);CheckShape(roof.parapet);CheckShape(roof.coping);CheckShape(roof.zone);
        }
        Floor penthouse=b.floors[5];
        if(penthouse.doors.Count(d=>d.name=="Elevator 3")!=1||penthouse.doors.Any(d=>d.name=="Elevator 1"||d.name=="Elevator 2"))
            throw new InvalidOperationException("The penthouse plan must contain only Elevator 3.");
        if(b.floors[4].flights.Count(fl=>fl.name.StartsWith("S4"))!=2||penthouse.flights.Length!=0)
            throw new InvalidOperationException("Stair 4 must connect Floor 5 to Floor 6 and stop there.");
        if(penthouse.serviceDeck==null||penthouse.serviceDeck.t==null||penthouse.serviceDeck.t.Length==0||penthouse.serviceFlights==null||penthouse.serviceFlights.Length!=2||penthouse.serviceHeaders==null)
            throw new InvalidOperationException("The penthouse service landing is incomplete.");
        CheckShape(penthouse.serviceDeck);foreach(Shape header in penthouse.serviceHeaders)CheckShape(header);
        if(b.floors[1].doors.Count(d=>d.name=="226 paired vestibule doorway")!=2)throw new InvalidOperationException("226 must retain both adjacent entrances.");
    }
    static void CheckCommonFrame(Bundle b)
    {
        if(b.envelope==null)throw new InvalidOperationException("The shared exterior frame is missing.");
        foreach(Floor floor in b.floors)
        {
            // The sixth-floor rooms occupy only the drawn penthouse footprint.
            if(floor.number==6)continue;
            float east=float.PositiveInfinity,west=float.NegativeInfinity,north=float.NegativeInfinity;
            for(int i=0;i<floor.slab.v.Length;i+=2)
            {north=Mathf.Max(north,floor.slab.v[i]);east=Mathf.Min(east,floor.slab.v[i+1]);west=Mathf.Max(west,floor.slab.v[i+1]);}
            if(Mathf.Abs(east-b.envelope.east)>.002f||Mathf.Abs(west-b.envelope.west)>.002f||Mathf.Abs(north-106.601895f)>.002f)
                throw new InvalidOperationException("Floor "+floor.number+" does not meet the common slab frame.");
            foreach(Facade face in floor.facades)
                if(Mathf.Abs(face.z-(face.normal>0?b.envelope.west:b.envelope.east))>.002f)
                    throw new InvalidOperationException("Floor "+floor.number+" has an unregistered facade plane.");
            float wallNorth=float.NegativeInfinity,wallSouth=float.PositiveInfinity;
            foreach(WallPart wall in floor.walls)for(int i=0;i<wall.mesh.v.Length;i+=2)
            {wallNorth=Mathf.Max(wallNorth,wall.mesh.v[i]);wallSouth=Mathf.Min(wallSouth,wall.mesh.v[i]);}
            if(Mathf.Abs(wallNorth-b.envelope.north)>.002f||(floor.number>=3&&Mathf.Abs(wallSouth-b.envelope.upperSouth)>.002f))
                throw new InvalidOperationException("Floor "+floor.number+" does not meet the common end-wall frame.");
        }
    }
    static void CheckShape(Shape s)
    {
        if(s==null||s.v==null||s.t==null||s.rings==null||s.v.Length%2!=0||s.t.Length%3!=0)throw new InvalidOperationException("Invalid mesh data.");
        foreach(int i in s.t)if(i<0||i>=s.v.Length/2)throw new InvalidOperationException("A mesh triangle references a missing vertex.");
        foreach(Ring r in s.rings)if(r.count<3||r.first<0||r.first+r.count>s.v.Length/2)
            throw new InvalidOperationException("A wall boundary references missing vertices.");
    }
    void ValidateOnly()
    {
        buildStage="validating embedded plans";
        try{Clamp();ValidateData();lastBuildError="";status="v6.7: loaded 6/6 floor plans. All six plans and roofs validated. Click Generate / Replace Complete Building to create the scene objects.";}
        catch(ExitGUIException){throw;}
        catch(Exception error){ReportFailure(error);}
    }
    void Generate()
    {
        if(IsPlaySession){status="Stop Play Mode before generating the building.";Repaint();return;}
        GameObject pending=null;int undo=-1;bool committed=false;
        try
        {
            buildStage="validating embedded plans";Clamp();ValidateData();
            buildStage="preparing asset folders and materials";EnsureFolders();EnsureMaterials();
            // Finish all texture importing before constructing a scene root.
            // The delayCall entry point runs outside OnGUI, and reference
            // construction below performs no imports or texture reimports.
            referenceMaterials.Clear();
            foreach(Floor floor in Data().floors)
            {buildStage="preparing Floor "+floor.number+" reference";referenceMaterials[floor.number]=PrepareReference(floor);}
            windowProbes.Clear();
            string buildName="Build_"+Guid.NewGuid().ToString("N");
            meshBuildFolder=Folder+"/"+buildName;AssetDatabase.CreateFolder(Folder,buildName);
            GameObject old=FindBuilding();Vector3 pos=old!=null?old.transform.position:Vector3.zero;Quaternion rot=old!=null?old.transform.rotation:Quaternion.identity;
            Undo.IncrementCurrentGroup();undo=Undo.GetCurrentGroup();Undo.SetCurrentGroupName("Rebuild Building 9 from source vectors");
            pending=new GameObject(RootName+" (building)");pending.transform.SetPositionAndRotation(pos,rot);pending.transform.localScale=Vector3.one*buildingScale;
            Group("Stair connections",pending.transform);
            foreach(Floor floor in Data().floors)
            {buildStage="generating Floor "+floor.number;BuildFloor(pending.transform,floor);}
            buildStage="generating roofs";BuildRoofs(pending.transform);
            if(includeSite){buildStage="generating site";BuildSite(Group("Site",pending.transform));}
            buildStage="checking generated floors and roofs";
            CheckGeneratedFrame(pending.transform);
            CheckGeneratedWallSolids(pending.transform);
            CheckGeneratedRoofs(pending.transform);
            CheckGeneratedFeatures(pending.transform);
            if(colliders){CheckWindowSightlines(pending.transform);CheckGeneratedArchitecture(pending.transform);CheckGeneratedStairHeadroom(pending.transform);}
            buildStage="saving generated assets";AssetDatabase.SaveAssets();
            buildStage="replacing the previous building";
            Undo.RegisterCreatedObjectUndo(pending,"Rebuild Building 9");
            foreach(GameObject root in SceneManager.GetActiveScene().GetRootGameObjects())
                if(root!=pending&&(root.name==RootName||root.name=="Engineering Building - Floor 1"))Undo.DestroyObjectImmediate(root);
            pending.name=RootName;Undo.CollapseUndoOperations(undo);committed=true;
            lastBuildError="";status="v6.7 generated: Floors 1--6 and roofs. "+
                (colliders?windowProbes.Count+" outward window sightlines are clear; doorway, landing and exterior seam checks passed.":"Collider-based architectural checks are disabled.")+" Save your scene with Ctrl+S.";
            Selection.activeGameObject=pending;pending=null;SyncLabels();Dirty();SceneView.lastActiveSceneView?.FrameSelected();
        }
        // Unity uses this exception to end an editor GUI pass. It must never
        // be swallowed and followed by more GUILayout calls.
        catch(ExitGUIException)
        {
            if(!committed)status="Unity refreshed the editor during "+buildStage+". Click Generate again after the refresh finishes.";
            throw;
        }
        catch(Exception error){ReportFailure(error);}
        finally
        {
            if(!committed)
            {
                if(undo>=0)Undo.RevertAllDownToGroup(undo);
                if(pending!=null)DestroyImmediate(pending);
                if(!string.IsNullOrEmpty(meshBuildFolder)&&AssetDatabase.IsValidFolder(meshBuildFolder))AssetDatabase.DeleteAsset(meshBuildFolder);
            }
            meshBuildFolder=null;windowProbes.Clear();referenceMaterials.Clear();
        }
    }
    void BuildFloor(Transform root,Floor f)
    {
        Transform level=Group("Floor "+f.number,root);level.localPosition=Vector3.up*((f.number-1)*floorHeight);
        Transform surfaces=Group("Floors",level),walls=Group("Traced walls",level),labels=Group("Room labels",level);
        Transform flights=Group("From Floor "+f.number,root.Find("Stair connections"));flights.localPosition=level.localPosition;
        MeshObject(surfaces,"Continuous slab",Extrude(f.slab,-floorSlabDepth,p=>0),"Corridor",$"F{f.number}_Slab",colliders);
        foreach(Finish finish in f.finishes)MeshObject(surfaces,finish.category+" source finishes",Surface(finish.mesh,.006f),finish.category,$"F{f.number}_{finish.category}",false);
        for(int i=0;i<f.walls.Length;i++)
        {
            WallPart w=f.walls[i];Profile pr=w.profile;
            Func<Vector2,float> top=p=>floorHeight-floorSlabDepth;
            if(pr.h0>=0)
            {
                Vector2 a=new Vector2(pr.a[0],pr.a[1]),b=new Vector2(pr.b[0],pr.b[1]);Vector2 delta=b-a;
                float y0=pr.h0*floorHeight+pr.startOffset,y1=pr.h1*floorHeight;
                top=p=>Mathf.Clamp(Mathf.Lerp(y0,y1,Mathf.Clamp01(Vector2.Dot(p-a,delta)/Mathf.Max(delta.sqrMagnitude,.0001f)))-.25f,0,floorHeight-floorSlabDepth);
            }
            MeshObject(walls,pr.h0<0?"Source wall union":"Traced wall below stair",Extrude(w.mesh,0,top),"Wall",$"F{f.number}_Walls_{i}",colliders);
        }
        for(int i=0;i<f.headers.Length;i++)MeshObject(walls,"Lintel at source gap",Extrude(f.headers[i],openingHeadHeight,p=>floorHeight-floorSlabDepth),"Wall",$"F{f.number}_Lintel_{i}",colliders);
        if(f.entryHeader.t.Length>0)
            MeshObject(walls,"Head above entrance glazing",Extrude(f.entryHeader,EntryWindowHeight(),p=>floorHeight-floorSlabDepth),"Wall",$"F{f.number}_EntryHeader",colliders);
        if(f.serviceHeaders!=null)for(int i=0;i<f.serviceHeaders.Length;i++)
            MeshObject(walls,"Service landing lintel",Extrude(f.serviceHeaders[i],openingHeadHeight+penthouseServiceRise,p=>floorHeight-floorSlabDepth),"Wall",$"F{f.number}_ServiceLintel_{i}",colliders);
        Transform exterior=Group("Exterior windows and panels",level);
        foreach(Facade facade in f.facades)BuildFacade(exterior,facade);
        if(f.entryWindows.Length>0)
        {
            Transform entrance=Group("Entrance glazing",level);
            foreach(EntryWindow window in f.entryWindows)BuildEntryWindow(entrance,window);
        }
        int index=0;
        foreach(Landing landing in f.landings)
        {
            float y=landing.height*floorHeight+landing.offset,bottom=landing.offset>0?-.12f:y-.16f;
            string name=landing.offset>0?"Raised S3 exit landing and square porch":(landing.height==0?"Ground exit landing":"Level half-height landing");
            MeshObject(landing.height==0?surfaces:flights,name,Extrude(landing.mesh,bottom,p=>y),landing.height==0?"Concrete":"Stair",$"F{f.number}_Landing_{index++}",colliders);
        }
        foreach(Flight flight in f.flights)BuildFlight(flights,flight);
        foreach(WellGuard guard in f.wellGuards)BuildWellGuard(level,guard);
        if(f.number==1)BuildSouthEntrance(level,Data().southEntrance);
        if(f.serviceDeck!=null&&f.serviceDeck.t!=null&&f.serviceDeck.t.Length>0)
        {
            MeshObject(surfaces,"Raised 603B floor and service landing",Extrude(f.serviceDeck,0,p=>penthouseServiceRise),"Operations",$"F{f.number}_ServiceDeck",colliders);
            Transform service=Group("603B service steps",level);
            foreach(Flight flight in f.serviceFlights)BuildFlight(service,flight,penthouseServiceRise);
            if(f.serviceGuard!=null&&f.serviceGuard.Length==4)
            {
                float y=penthouseServiceRise+.95f;
                Vector3 a=new Vector3(f.serviceGuard[0],y,f.serviceGuard[1]),b=new Vector3(f.serviceGuard[2],y,f.serviceGuard[3]);
                Beam(service,a,b,.05f);Beam(service,a-Vector3.up*.95f,a,.045f);Beam(service,b-Vector3.up*.95f,b,.045f);
            }
        }
        foreach(Landing landing in f.landings)if(landing.height>0)LandingGuards(flights,landing,f.flights);
        if(f.exterior!=null&&f.exterior.count>0)BuildExteriorSteps(level,f.exterior);
        foreach(Door door in f.doors)BuildDoor(level,door);
        if(f.piano!=null&&f.piano.Length==2)BuildPiano(Group("North-facing lobby piano",level),f.piano);
        foreach(LabelData label in f.labels)Label(labels,label.text,new Vector3(label.x,.025f+(label.service?penthouseServiceRise:0),label.z));
        BuildReference(level,f);
    }
    void FacadeBox(Transform parent,string name,float x0,float x1,float y0,float y1,float z,float depth,string material,bool solid)
    {
        if(x1-x0<.001f||y1-y0<.001f)return;
        Box(parent,name,new Vector3((x0+x1)/2,(y0+y1)/2,z),new Vector3(x1-x0,y1-y0,depth),material,solid);
    }
    void Glazing(Transform parent,string name,float x0,float x1,float y0,float y1,float z,Facade f)
    {
        FacadeBox(parent,name,x0,x1,y0,y1,z,.04f,"Window glass",colliders);
        windowProbes.Add(new WindowProbe{owner=parent,point=new Vector3((x0+x1)/2,(y0+y1)/2,z+f.normal*.045f),direction=new Vector3(0,0,f.normal)});
    }
    void CheckWindowSightlines(Transform generatedRoot)
    {
        Physics.SyncTransforms();
        foreach(WindowProbe probe in windowProbes)
        {
            Vector3 start=probe.owner.TransformPoint(probe.point);
            Vector3 direction=probe.owner.TransformDirection(probe.direction).normalized;
            foreach(RaycastHit hit in Physics.RaycastAll(start,direction,probe.clearDistance*buildingScale,~0,QueryTriggerInteraction.Ignore))
            {
                if(!hit.transform.IsChildOf(generatedRoot))continue;
                string where=probe.owner.name;Transform p=probe.owner.parent;
                while(p!=null&&p!=generatedRoot){where=p.name+"/"+where;p=p.parent;}
                throw new InvalidOperationException("Window sightline blocked in "+where+" by "+hit.collider.name+
                    ". The previous building was kept; inspect this geometry before retrying.");
            }
        }
    }
    void CheckGeneratedWallSolids(Transform generatedRoot)
    {
        for(int n=1;n<=FloorCount;n++)
        {
            Transform walls=generatedRoot.Find("Floor "+n+"/Traced walls");
            if(walls==null||!walls.GetComponentsInChildren<MeshFilter>().Any(m=>m.sharedMesh!=null&&
                m.sharedMesh.vertexCount>0&&m.sharedMesh.bounds.size.y>=floorHeight-floorSlabDepth-.02f))
                throw new InvalidOperationException("Floor "+n+" did not produce a full-height wall mesh. The previous building was kept.");
        }
    }
    void CheckGeneratedStairHeadroom(Transform generatedRoot)
    {
        float scale=generatedRoot.lossyScale.x;
        foreach(Floor floor in Data().floors)
        {
            if(floor.number>=FloorCount)continue;
            Transform lower=generatedRoot.Find("Floor "+floor.number),upper=generatedRoot.Find("Floor "+(floor.number+1));
            MeshCollider[] ceilings=upper.Find("Floors").GetComponentsInChildren<MeshCollider>(true);
            foreach(Flight flight in floor.flights)
            {
                Vector3 a=new Vector3(flight.a[0],0,flight.a[1]),b=new Vector3(flight.b[0],0,flight.b[1]);
                Vector3 right=Vector3.Cross(Vector3.up,(b-a).normalized);
                float rise=(flight.h1-flight.h0)*floorHeight-flight.startOffset;int count=Mathf.CeilToInt(rise/.19f);
                for(int tread=0;tread<count;tread++)
                {
                    float height=flight.h0*floorHeight+flight.startOffset+rise*(tread+1)/count;
                    foreach(float fraction in new[]{.02f,.5f,.98f})foreach(float offset in new[]{-.35f,0,.35f})
                    {
                        Vector3 position=Vector3.Lerp(a,b,(tread+fraction)/count)+right*offset+Vector3.up*(height+.01f);
                        Ray ray=new Ray(lower.TransformPoint(position),lower.TransformDirection(Vector3.up));
                        foreach(MeshCollider ceiling in ceilings)if(ceiling.Raycast(ray,out RaycastHit hit,1.785f*scale))
                            throw new InvalidOperationException("Insufficient headroom above "+flight.name+" from Floor "+floor.number+" at tread "+(tread+1)+". The previous building was kept.");
                    }
                }
            }
        }
    }
    void CheckGeneratedFeatures(Transform generatedRoot)
    {
        foreach(Floor floor in Data().floors)
        {
            Transform level=generatedRoot.Find("Floor "+floor.number);
            Transform labels=level.Find("Room labels"),stairs=generatedRoot.Find("Stair connections/From Floor "+floor.number);
            if(labels==null||labels.childCount!=floor.labels.Length||stairs==null)
                throw new InvalidOperationException("Generated room labels or stair group missing on Floor "+floor.number);
            foreach(Door door in floor.doors)
                if(level.Find(door.name+" - "+door.kind)==null)
                    throw new InvalidOperationException("Missing door assembly: "+door.name);
            if(floor.entryWindows.Length>0)
            {
                Transform entrance=level.Find("Entrance glazing");
                if(entrance==null||entrance.childCount!=floor.entryWindows.Length)
                    throw new InvalidOperationException("Entrance window assemblies are missing on Floor "+floor.number);
                foreach(EntryWindow window in floor.entryWindows)
                    if(entrance.Find(window.name)==null)throw new InvalidOperationException("Missing entrance window: "+window.name);
            }
            if(floor.number==1)
            {
                Transform vending=level.Find("Covered breezeway paving and seating/Vending machines");
                if(vending==null||vending.childCount!=2)throw new InvalidOperationException("The breezeway vending machines were not created.");
            }
            foreach(Flight flight in floor.flights)
                if(stairs.Find(flight.name)==null)throw new InvalidOperationException("Missing stair flight: "+flight.name);
            if(floor.piano!=null&&floor.piano.Length==2&&level.Find("North-facing lobby piano")==null)
                throw new InvalidOperationException("The lobby piano was not created.");
        }
    }
    static bool WallCrossesSegment(MeshCollider wall,Vector3 start,Vector3 end)
    {
        // A ray beginning inside a closed triangle mesh can miss its outward
        // backface. Probe from both ends without changing the global physics
        // backface setting. This also catches obstructions facing either way.
        Vector3 segment=end-start;float length=segment.magnitude;
        if(length<.00001f)return false;
        Vector3 direction=segment/length;
        return wall.Raycast(new Ray(start,direction),out RaycastHit forward,length)||
            wall.Raycast(new Ray(end,-direction),out RaycastHit reverse,length);
    }
    void CheckGeneratedArchitecture(Transform generatedRoot)
    {
        Physics.SyncTransforms();
        MeshCollider[] all=generatedRoot.GetComponentsInChildren<MeshCollider>(true);
        float scale=generatedRoot.lossyScale.x;
        foreach(PortalCheck portal in Data().architecture.portals)
        {
            Transform level=generatedRoot.Find("Floor "+portal.floor);
            MeshCollider[] walls=level.Find("Traced walls").GetComponentsInChildren<MeshCollider>(true);
            Quaternion orientation=Quaternion.Euler(0,portal.yaw,0);
            Vector3 normal=orientation*Vector3.forward,right=orientation*Vector3.right;
            foreach(float offset in new[]{-.35f,0,.35f})
            {
                Vector3 local=new Vector3(portal.x,portal.yOffset+1.05f,portal.z)+right*(offset*portal.width);
                Vector3 from=level.TransformPoint(local-normal*.32f),to=level.TransformPoint(local+normal*.32f);
                foreach(MeshCollider wall in walls)if(WallCrossesSegment(wall,from,to))
                    throw new InvalidOperationException("Wall blocks doorway: "+portal.name+". The previous building was kept.");
            }
            // Either side of the threshold may meet the indoor slab or a roof /
            // exterior landing. Test both so an exact triangle edge is harmless.
            bool supported=false;
            foreach(float offset in new[]{-.10f,.10f})
            {
                Vector3 point=level.TransformPoint(new Vector3(portal.x,portal.yOffset+.15f,portal.z)+normal*offset);
                Vector3 down=level.TransformDirection(Vector3.down);
                foreach(MeshCollider solid in all)if(solid.Raycast(new Ray(point,down),out RaycastHit hit,.70f*scale))
                {supported=true;break;}
                if(supported)break;
            }
            if(!supported)throw new InvalidOperationException("No floor or landing below doorway: "+portal.name);
        }
        foreach(SeamCheck seam in Data().architecture.seams)
        {
            Transform level=generatedRoot.Find("Floor "+seam.floor);
            Vector3 normal=Quaternion.Euler(0,seam.yaw,0)*Vector3.forward;
            Vector3 local=new Vector3(seam.x,seam.height>0?seam.height:1.05f,seam.z);
            Vector3 start=level.TransformPoint(local-normal*.32f),end=level.TransformPoint(local+normal*.32f);
            bool closed=false;
            foreach(MeshCollider wall in level.Find("Traced walls").GetComponentsInChildren<MeshCollider>(true))
                if(WallCrossesSegment(wall,start,end)){closed=true;break;}
            if(!closed)throw new InvalidOperationException("Exterior seam is still open on Floor "+seam.floor+": "+seam.name);
        }
    }
    void CheckGeneratedRoofs(Transform generatedRoot)
    {
        Transform roofs=generatedRoot.Find("Roofs");
        if(roofs==null)throw new InvalidOperationException("Roof objects were not created.");
        foreach(Roof roof in Data().roofs)
        {
            Transform part=roofs.Find(roof.name);
            if(part==null||!part.GetComponentsInChildren<MeshFilter>(true).Any(m=>m.sharedMesh!=null&&m.sharedMesh.vertexCount>0))
                throw new InvalidOperationException("Missing generated roof: "+roof.name);
        }
    }
    void CheckGeneratedFrame(Transform generatedRoot)
    {
        foreach(Floor floor in Data().floors)
        {
            Transform level=generatedRoot.Find("Floor "+floor.number);
            if(level==null||(level.localScale-Vector3.one).sqrMagnitude>.000001f||level.localRotation!=Quaternion.identity||
                new Vector2(level.localPosition.x,level.localPosition.z).sqrMagnitude>.000001f)
                throw new InvalidOperationException("Floor "+floor.number+" received an independent scale, rotation or horizontal offset.");
        }
    }
    void BuildFacade(Transform parent,Facade f)
    {
        Transform face=Group(f.name,parent);bool tower=f.profile=="Tower";
        float sill=tower?towerWindowSill:wingWindowSill;
        float head=sill+(tower?towerWindowHeight:wingWindowHeight);
        float ceiling=floorHeight-floorSlabDepth;
        float panelZ=f.z-f.normal*f.depth/2;
        // The inner glass face meets the clipped room-wall ends exactly. There
        // is no passage around a room divider behind the recessed glazing.
        const float glassDepth=.04f,bar=.055f;
        float glassZ=f.z-f.normal*(f.depth-glassDepth/2);
        float frameZ=glassZ+f.normal*.025f;
        string panel=tower?"Facade panel":"Wing brick panel";
        string frame=tower?"Window silver":"Window brown";
        float projection=tower?.26f:.12f;
        for(int i=0;i<f.posts.Length;i++)
        {
            float x=f.posts[i];
            FacadeBox(face,"Structural white pier",x-f.postWidth/2,x+f.postWidth/2,0,ceiling,
                f.z+f.normal*(projection-f.depth)/2,f.depth+projection,"Facade white",colliders);
        }
        for(int i=0;i<f.posts.Length-1;i++)
        {
            float a=f.posts[i]+f.postWidth/2,b=f.posts[i+1]-f.postWidth/2,w=b-a;
            Transform bay=Group("Bay "+(i+1)+" - raised window",face);
            FacadeBox(bay,"Solid wall below sill",a,b,0,sill,panelZ,f.depth,panel,colliders);
            FacadeBox(bay,"Solid wall above window",a,b,head,ceiling,panelZ,f.depth,tower?panel:"Facade white",colliders);
            FacadeBox(bay,"Raised sill frame",a,b,sill,sill+bar,frameZ,.08f,frame,false);
            FacadeBox(bay,"Window head frame",a,b,head-bar,head,frameZ,.08f,frame,false);
            int panes=Mathf.Clamp(Mathf.RoundToInt(w/(tower?.86f:.82f)),2,9);
            for(int j=0;j<=panes;j++)
            {
                float x=Mathf.Lerp(a,b,(float)j/panes);
                FacadeBox(bay,"Window mullion",x-bar/2,x+bar/2,sill,head,frameZ,.08f,frame,false);
            }
            float middle=(sill+head)/2;
            if(!tower)FacadeBox(bay,"Wing window transom",a,b,middle-bar/2,middle+bar/2,frameZ,.08f,frame,false);
            for(int j=0;j<panes;j++)
            {
                float left=Mathf.Lerp(a,b,(float)j/panes)+bar/2;
                float right=Mathf.Lerp(a,b,(float)(j+1)/panes)-bar/2;
                if(tower)
                    Glazing(bay,"Raised glazing",left,right,sill+bar,head-bar,glassZ,f);
                else
                {
                    Glazing(bay,"Wing lower glazing",left,right,sill+bar,middle-bar/2,glassZ,f);
                    Glazing(bay,"Wing upper glazing",left,right,middle+bar/2,head-bar,glassZ,f);
                }
            }
            if(tower)
            {
                // Pale metal shade panels sit above, not across, the glazing.
                float bottom=head+.045f,top=Mathf.Min(ceiling-.08f,bottom+.38f);
                float shadeZ=f.z+f.normal*.12f;
                FacadeBox(bay,"Pale sunshade above glazing",a,b,bottom,top,shadeZ,.055f,"Facade white",false);
                for(int rib=1;rib<=3;rib++)
                {
                    float y=Mathf.Lerp(bottom,top,rib/4f);
                    FacadeBox(bay,"Sunshade horizontal rib",a+.03f,b-.03f,y-.008f,y+.008f,shadeZ+f.normal*.034f,.012f,"Shade detail",false);
                }
                // Subtle panel joints stop at the raised sill.
                for(int joint=1;joint<=2;joint++)
                {
                    float x=Mathf.Lerp(a,b,joint/3f);
                    FacadeBox(bay,"Panel joint",x-.006f,x+.006f,.06f,sill-.04f,f.z+f.normal*.004f,.008f,"Panel joint",false);
                }
            }
        }
        // A shallow white cover conceals the exposed slab edge; it does not
        // alter the slab, floor openings, or the floor-to-floor height.
        FacadeBox(face,"White slab-edge band",f.x0,f.x1,ceiling,floorHeight,f.z+f.normal*.035f,.07f,"Facade white",false);
    }
    Mesh Surface(Shape s,float y)
    {
        var vs=new List<Vector3>();for(int i=0;i<s.v.Length;i+=2)vs.Add(new Vector3(s.v[i],y,s.v[i+1]));
        var tris=new List<int>();for(int i=0;i<s.t.Length;i+=3)UpTriangle(vs,tris,s.t[i],s.t[i+1],s.t[i+2]);
        return MakeMesh(vs,tris);
    }
    Mesh Extrude(Shape s,float bottom,Func<Vector2,float> top)
    {
        int n=s.v.Length/2;var vs=new List<Vector3>();var tris=new List<int>();
        for(int i=0;i<n;i++)vs.Add(new Vector3(s.v[2*i],bottom,s.v[2*i+1]));
        for(int i=0;i<n;i++)vs.Add(new Vector3(s.v[2*i],Mathf.Max(bottom,top(new Vector2(s.v[2*i],s.v[2*i+1]))),s.v[2*i+1]));
        for(int i=0;i<s.t.Length;i+=3)
        {
            int a=s.t[i],b=s.t[i+1],c=s.t[i+2];
            UpTriangle(vs,tris,a+n,b+n,c+n);DownTriangle(vs,tris,a,b,c);
        }
        foreach(Ring r in s.rings)for(int j=0;j<r.count;j++)
        {
            int a=r.first+j,b=r.first+(j+1)%r.count,k=vs.Count;
            vs.Add(vs[a]);vs.Add(vs[b]);vs.Add(vs[b+n]);vs.Add(vs[a+n]);
            Triangle(vs,tris,k,k+1,k+2);Triangle(vs,tris,k,k+2,k+3);
        }
        return MakeMesh(vs,tris);
    }
    static void Triangle(List<Vector3> v,List<int> t,int a,int b,int c)
    {if(Vector3.Cross(v[b]-v[a],v[c]-v[a]).sqrMagnitude<1e-12f)return;t.Add(a);t.Add(b);t.Add(c);}
    static void UpTriangle(List<Vector3> v,List<int> t,int a,int b,int c)
    {if(Vector3.Cross(v[b]-v[a],v[c]-v[a]).y<0)Triangle(v,t,a,c,b);else Triangle(v,t,a,b,c);}
    static void DownTriangle(List<Vector3> v,List<int> t,int a,int b,int c)
    {if(Vector3.Cross(v[b]-v[a],v[c]-v[a]).y>0)Triangle(v,t,a,c,b);else Triangle(v,t,a,b,c);}
    static Mesh MakeMesh(List<Vector3> v,List<int> t)
    {Mesh m=new Mesh{indexFormat=IndexFormat.UInt32};m.SetVertices(v);m.SetTriangles(t,0);m.RecalculateNormals();m.RecalculateBounds();return m;}
    Mesh Persist(Mesh m,string key)
    {
        // Do not CopySerialized over a mesh that a renderer already holds.
        // Fresh native mesh buffers avoid stale faces/indices after regeneration,
        // and retain the previous mesh assets for scene Undo.
        if(string.IsNullOrEmpty(meshBuildFolder)||!AssetDatabase.IsValidFolder(meshBuildFolder))
            throw new InvalidOperationException("No active mesh output folder. Generate the complete building again.");
        string path=AssetDatabase.GenerateUniqueAssetPath(meshBuildFolder+"/"+key+".asset");
        m.name=key;
        AssetDatabase.CreateAsset(m,path);m.UploadMeshData(false);return m;
    }
    GameObject MeshObject(Transform parent,string name,Mesh mesh,string material,string key,bool solid)
    {
        Transform t=Group(name,parent);Mesh saved=Persist(mesh,key);t.gameObject.AddComponent<MeshFilter>().sharedMesh=saved;
        t.gameObject.AddComponent<MeshRenderer>().sharedMaterial=materials[material];
        if(solid)t.gameObject.AddComponent<MeshCollider>().sharedMesh=saved;return t.gameObject;
    }
    void BuildFlight(Transform parent,Flight f,float heightScale=-1)
    {
        float riseScale=heightScale>0?heightScale:floorHeight;
        Transform t=Group(f.name,parent);Vector3 a=new Vector3(f.a[0],f.h0*riseScale+f.startOffset,f.a[1]),b=new Vector3(f.b[0],f.h1*riseScale,f.b[1]);
        Vector3 flat=b-a;flat.y=0;float length=flat.magnitude;Vector3 dir=flat/length,right=Vector3.Cross(Vector3.up,dir);
        int count=Mathf.Max(1,Mathf.CeilToInt((b.y-a.y)/.19f));float run=length/count,rise=(b.y-a.y)/count;
        for(int i=0;i<count;i++)
        {
            float h=rise*(i+1),deck=Mathf.Max(.16f,rise+.02f);Vector3 pos=a+dir*((i+.5f)*run)+Vector3.up*(h-deck/2);
            GameObject step=Box(t,"Tread "+(i+1),pos,new Vector3(f.width,deck,run),"Stair",colliders);step.transform.localRotation=Quaternion.LookRotation(dir);
            GameObject edge=Box(t,"Yellow tread nosing",a+dir*(i*run+.025f)+Vector3.up*(h+.004f),new Vector3(f.width-.06f,.008f,.045f),"Nosing",false);edge.transform.localRotation=Quaternion.LookRotation(dir);
            if(i%3==0||i==count-1)foreach(int side in new[]{-1,1})
            {Vector3 foot=a+dir*((i+.5f)*run)+Vector3.up*h+right*(side*(f.width/2-.04f));Beam(t,foot,foot+Vector3.up,.045f);}
        }
        foreach(int side in new[]{-1,1}){Vector3 off=right*(side*(f.width/2-.04f));Beam(t,a+off+Vector3.up*(1+rise),b+off+Vector3.up,.05f);}
    }
    static bool OnSegment(Vector2 p,Vector2 a,Vector2 b)
    {Vector2 d=b-a;float t=Mathf.Clamp01(Vector2.Dot(p-a,d)/Mathf.Max(d.sqrMagnitude,.00001f));return Vector2.Distance(p,a+t*d)<.10f;}
    void LandingGuards(Transform parent,Landing landing,Flight[] flights)
    {
        Transform guard=Group("Half-landing open interfaces and guards",parent);float y=landing.height*floorHeight;
        foreach(Ring ring in landing.mesh.rings)for(int j=0;j<ring.count;j++)
        {
            int a=ring.first+j,b=ring.first+(j+1)%ring.count;
            Vector2 p=new Vector2(landing.mesh.v[2*a],landing.mesh.v[2*a+1]),q=new Vector2(landing.mesh.v[2*b],landing.mesh.v[2*b+1]);
            bool entrance=flights.Any(fl=>(Mathf.Abs(fl.h0-landing.height)<.01f && OnSegment(new Vector2(fl.a[0],fl.a[1]),p,q)) ||
                (Mathf.Abs(fl.h1-landing.height)<.01f && OnSegment(new Vector2(fl.b[0],fl.b[1]),p,q)));
            if(entrance)continue;Vector3 start=new Vector3(p.x,y+.95f,p.y),end=new Vector3(q.x,y+.95f,q.y);
            Beam(guard,start,end,.05f);Beam(guard,start-Vector3.up*.95f,start,.045f);Beam(guard,end-Vector3.up*.95f,end,.045f);
        }
    }
    void BuildWellGuard(Transform level,WellGuard guard)
    {
        Transform t=Group(guard.name,level);
        Vector3 a=new Vector3(guard.a[0],0,guard.a[1]),b=new Vector3(guard.b[0],0,guard.b[1]);
        foreach(float height in new[]{guard.height,guard.height/2})Beam(t,a+Vector3.up*height,b+Vector3.up*height,.045f);
        int posts=Mathf.Max(1,Mathf.CeilToInt(Vector3.Distance(a,b)));
        for(int i=0;i<=posts;i++){Vector3 foot=Vector3.Lerp(a,b,(float)i/posts);Beam(t,foot,foot+Vector3.up*guard.height,.045f);}
    }
    void BuildExteriorSteps(Transform level,Exterior e)
    {
        Transform t=Group("S3 square porch, three steps and connected railings",level);
        float grade=e.landingHeight-e.drop;
        MeshObject(t,"Ground at porch and stair foot",Extrude(e.ground,grade-.22f,p=>grade-.02f),"Terrain","S3_ExteriorGrade",colliders);
        MeshObject(t,"Level concrete approach",Extrude(e.apron,grade-.14f,p=>grade),"Concrete","S3_Apron",colliders);
        MeshObject(t,"Head above raised S3 exit",Extrude(e.header,e.landingHeight+EntryWindowHeight(),p=>floorHeight-floorSlabDepth),"Wall","S3_RaisedDoorHead",colliders);
        Vector3 a=new Vector3(e.a[0],0,e.a[1]),b=new Vector3(e.b[0],0,e.b[1]);
        Vector3 dir=(b-a).normalized;float run=Vector3.Distance(a,b)/e.count;
        for(int i=0;i<e.count;i++)
        {
            float top=e.landingHeight-e.drop*(i+1)/e.count,height=top-(grade-.12f);
            GameObject step=Box(t,"Exterior concrete step "+(i+1),a+dir*((i+.5f)*run)+Vector3.up*(top-height/2),new Vector3(e.width,height,run),"Concrete",colliders);
            step.transform.localRotation=Quaternion.LookRotation(dir);
        }
        float minX=float.PositiveInfinity,maxX=float.NegativeInfinity,minZ=float.PositiveInfinity,maxZ=float.NegativeInfinity;
        for(int i=0;i<e.porch.v.Length;i+=2)
        {minX=Mathf.Min(minX,e.porch.v[i]);maxX=Mathf.Max(maxX,e.porch.v[i]);minZ=Mathf.Min(minZ,e.porch.v[i+1]);maxZ=Mathf.Max(maxZ,e.porch.v[i+1]);}
        float centreZ=(minZ+maxZ)/2,porchWidth=maxZ-minZ;
        foreach(int side in new[]{-1,1})
        {
            Transform rails=Group(side<0?"Porch and stair east rail":"Porch and stair west rail",t);
            Vector3 back=new Vector3(maxX-.04f,e.landingHeight,centreZ+side*(porchWidth/2-.04f));
            Vector3 front=new Vector3(minX+.04f,e.landingHeight,back.z);
            Vector3 stairTop=new Vector3(a.x,e.landingHeight,centreZ+side*(e.width/2-.04f));
            Vector3 stairFoot=new Vector3(b.x,grade,stairTop.z);
            foreach(float height in new[]{e.railHeight,e.railHeight/2})
            {
                Vector3 up=Vector3.up*height;
                Beam(rails,back+up,front+up,.045f);
                Beam(rails,front+up,stairTop+up,.045f);
                Beam(rails,stairTop+up,stairFoot+up,.045f);
            }
            foreach(float fraction in new[]{0,.5f,1})
            {Vector3 foot=Vector3.Lerp(back,front,fraction);Beam(rails,foot,foot+Vector3.up*e.railHeight,.045f);}
            Beam(rails,stairTop,stairTop+Vector3.up*e.railHeight,.045f);
            for(int i=0;i<e.count;i++)
            {
                float fraction=(i+.5f)/e.count;Vector3 line=Vector3.Lerp(stairTop,stairFoot,fraction),foot=line;
                foot.y=e.landingHeight-e.drop*(i+1)/e.count;
                Beam(rails,foot,line+Vector3.up*e.railHeight,.045f);
            }
            Beam(rails,stairFoot,stairFoot+Vector3.up*e.railHeight,.045f);
        }
    }
    void BuildDoor(Transform level,Door d)
    {
        Transform frame=Group(d.name+" - "+d.kind,level);frame.localPosition=new Vector3(d.x,(d.service?penthouseServiceRise:0)+d.yOffset,d.z);frame.localRotation=Quaternion.Euler(0,d.yaw,0);
        float width=d.width,h=Mathf.Min(2.08f,openingHeadHeight-.04f);
        if(d.kind=="GlassDouble"||d.kind=="GlassSingle"||d.kind=="FixedGlass")
        {BuildGlassDoubleDoors(frame,width,h,d.kind=="GlassDouble"?2:1,d.kind=="FixedGlass");return;}
        foreach(int side in new[]{-1,1})Box(frame,"Jamb",new Vector3(side*(width/2+.025f),h/2,0),new Vector3(.05f,h,.1f),"Metal",false);
        Box(frame,"Door head",new Vector3(0,h,0),new Vector3(width+.1f,.05f,.1f),"Metal",false);
        if(d.kind=="Frame")return;
        if(d.kind=="Sliding"||d.kind=="Elevator")
        {
            foreach(int side in new[]{-1,1})
                Box(frame,"Parked door leaf",new Vector3(side*width*.77f,h/2,.13f),new Vector3(width/2,h,.035f),d.kind=="Elevator"?"Metal":"Glass",false);
            if(d.kind=="Elevator")Box(frame,"Corridor-facing call panel",new Vector3(width/2+.15f,1.12f,.14f),new Vector3(.12f,.23f,.04f),"Metal",false);
            else Box(frame,"Automatic door sensor",new Vector3(0,h+.1f,.08f),new Vector3(.22f,.08f,.08f),"Metal",false);
        }
        else foreach(int side in d.kind=="Double"?new[]{-1,1}:new[]{-1})
        {
            float w=d.kind=="Double"?width/2:width;Transform hinge=Group("Push/pull hinge",frame);hinge.localPosition=new Vector3(side*width/2,0,0);hinge.localRotation=Quaternion.Euler(0,side<0?-82:82,0);
            Box(hinge,"Open leaf",new Vector3(-side*w/2,h/2,0),new Vector3(w,h,.035f),d.kind=="Service"?"Metal":"Glass",false);
            if(d.kind=="Service")for(int slat=0;slat<6;slat++)
                Box(hinge,"Service door vent slat",new Vector3(-side*w/2,.35f+slat*.055f,.025f),new Vector3(w*.65f,.018f,.018f),"Piano",false);
            Box(hinge,"Push/pull bar",new Vector3(-side*w/2,1,.04f),new Vector3(w*.7f,.03f,.03f),"Metal",false);
        }
    }
    void BuildGlassDoubleDoors(Transform frame,float width,float h,int leafCount=2,bool fixedPanel=false)
    {
        foreach(int side in new[]{-1,1})
            Box(frame,"Aluminium doorway jamb",new Vector3(side*(width/2+.045f),h/2,0),new Vector3(.09f,h,.28f),"Metal",false);
        Box(frame,"Aluminium doorway head",new Vector3(0,h+.035f,0),new Vector3(width+.18f,.07f,.28f),"Metal",false);
        for(int i=0;i<leafCount;i++)
        {
            int side=i==0?-1:1;float w=width/leafCount;
            Transform hinge=Group(fixedPanel?"Fixed glazed sidelight":"Swing glass leaf - open",frame);
            if(!fixedPanel){hinge.localPosition=new Vector3(side*width/2,0,0);hinge.localRotation=Quaternion.Euler(0,side<0?-82:82,0);}
            Transform leaf=Group("Framed glass leaf",hinge);
            if(!fixedPanel)leaf.localPosition=new Vector3(-side*w/2,0,0);
            Box(leaf,"Glazing visible from both faces",new Vector3(0,h/2,0),new Vector3(w-.10f,h-.16f,.035f),"Glass",fixedPanel&&colliders);
            foreach(int edge in new[]{-1,1})Box(leaf,"Vertical stile",new Vector3(edge*(w/2-.025f),h/2,0),new Vector3(.05f,h,.055f),"Metal",false);
            Box(leaf,"Top rail",new Vector3(0,h-.035f,0),new Vector3(w,.07f,.055f),"Metal",false);
            Box(leaf,"Bottom rail",new Vector3(0,.045f,0),new Vector3(w,.09f,.055f),"Metal",false);
            if(fixedPanel)continue;
            foreach(int face in new[]{-1,1})
            {
                float x=-side*(w/2-.14f),z=face*.07f;
                Box(leaf,"Push pull handle on each face",new Vector3(x,1.04f,z),new Vector3(.028f,.42f,.028f),"Metal",false);
                foreach(float y in new[]{.86f,1.22f})Box(leaf,"Handle mount",new Vector3(x,y,face*.045f),new Vector3(.028f,.028f,.065f),"Metal",false);
            }
        }
    }
    float EntryWindowHeight()
    {return Mathf.Min(2.08f,openingHeadHeight-.04f)+.07f;}
    void BuildEntryWindow(Transform parent,EntryWindow window)
    {
        Transform frame=Group(window.name,parent);
        frame.localPosition=new Vector3(window.x,0,window.z);frame.localRotation=Quaternion.Euler(0,window.yaw,0);
        float width=window.width,height=EntryWindowHeight();const float bar=.055f,glassDepth=.035f;
        foreach(int side in new[]{-1,1})
            Box(frame,"Outer vertical frame",new Vector3(side*(width/2-bar/2),height/2,0),new Vector3(bar,height,.08f),"Metal",colliders);
        foreach(float y in new[]{bar/2,height-bar/2})
            Box(frame,"Outer horizontal frame",new Vector3(0,y,0),new Vector3(width,bar,.08f),"Metal",colliders);
        Box(frame,"Central horizontal divider",new Vector3(0,height/2,0),new Vector3(width-2*bar,bar,.08f),"Metal",colliders);
        if(window.cross)
            Box(frame,"Central vertical divider",new Vector3(0,height/2,0),new Vector3(bar,height-2*bar,.08f),"Metal",colliders);
        int columns=window.cross?2:1;
        for(int column=0;column<columns;column++)for(int row=0;row<2;row++)
        {
            float x0=column==0?-width/2+bar:bar/2;
            float x1=columns==1?width/2-bar:(column==0?-bar/2:width/2-bar);
            float y0=row==0?bar:height/2+bar/2,y1=row==0?height/2-bar/2:height-bar;
            float x=(x0+x1)/2,y=(y0+y1)/2;
            Box(frame,"Fixed glass pane "+(column+1)+"-"+(row+1),new Vector3(x,y,0),new Vector3(x1-x0,y1-y0,glassDepth),"Glass",colliders);
            windowProbes.Add(new WindowProbe{owner=frame,point=new Vector3(x,y,glassDepth/2+.045f),direction=Vector3.forward,clearDistance=window.probeDistance>0?window.probeDistance:5});
        }
    }
    void BuildSouthEntrance(Transform level,SouthEntrance entrance)
    {
        Transform plaza=Group("Covered breezeway paving and seating",level);
        MeshObject(plaza,"Continuous concrete breezeway",Extrude(entrance.paving,-.16f,p=>0),"Concrete", "F1_BreezewayPaving",colliders);
        MeshObject(plaza,"Approach aligned with hallway openings",Surface(entrance.approach,.008f),"Corridor","F1_BreezewayApproach",false);
        MeshObject(plaza,"Vending machine concrete pad",Extrude(entrance.vendingPad,-.16f,p=>0),"Concrete","F1_VendingPad",colliders);
        Transform vending=Group("Vending machines",plaza);
        foreach(VendingMachine machine in entrance.vendingMachines)BuildVendingMachine(vending,machine);
        if(!includePicnicSeating)return;
        for(int i=0;i<Mathf.Min(picnicTableCount,entrance.tables.Length);i++)BuildPicnicTable(plaza,entrance.tables[i],i);
    }
    void BuildVendingMachine(Transform parent,VendingMachine machine)
    {
        Transform t=Group(machine.name,parent);t.localPosition=new Vector3(machine.x,0,machine.z);t.localRotation=Quaternion.Euler(0,machine.yaw,0);
        float w=machine.width,h=machine.height,d=machine.depth,front=d/2+.012f;
        string colour=machine.kind=="Snack"?"Vending blue":"Vending red";
        Box(t,"Cabinet",new Vector3(0,h/2,0),new Vector3(w,h,d),"Piano",colliders);
        Box(t,"Coloured front",new Vector3(0,h/2,front),new Vector3(w-.03f,h-.03f,.025f),colour,false);
        Box(t,"Product display backing",new Vector3(-w*.10f,h*.57f,front+.018f),new Vector3(w*.64f,h*.58f,.018f),"Piano",false);
        for(int row=0;row<4;row++)for(int column=0;column<3;column++)
        {
            float x=-w*.32f+column*w*.20f,y=h*.36f+row*h*.12f;
            Box(t,"Displayed product",new Vector3(x,y,front+.033f),new Vector3(w*.12f,h*.075f,.03f),(row+column)%2==0?"Ivory":colour,false);
        }
        Box(t,"Display glazing",new Vector3(-w*.10f,h*.57f,front+.055f),new Vector3(w*.64f,h*.58f,.015f),"Glass",false);
        Box(t,"Selection and payment panel",new Vector3(w*.34f,h*.57f,front+.035f),new Vector3(w*.16f,h*.37f,.025f),"Metal",false);
        for(int row=0;row<5;row++)Box(t,"Selection button",new Vector3(w*.34f,h*(.44f+row*.065f),front+.055f),new Vector3(w*.075f,.025f,.015f),"Ivory",false);
        Box(t,"Collection opening",new Vector3(0,h*.13f,front+.033f),new Vector3(w*.66f,h*.12f,.018f),"Piano",false);
        Transform sign=Group("Machine label",t);sign.localPosition=new Vector3(0,h*.94f,front+.05f);sign.localRotation=Quaternion.Euler(0,180,0);
        TextMesh label=sign.gameObject.AddComponent<TextMesh>();label.text=machine.kind=="Snack"?"SNACKS":"DRINKS";label.fontSize=32;label.characterSize=.035f;label.anchor=TextAnchor.MiddleCenter;label.color=Color.white;
        Font font=Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");label.font=font;sign.GetComponent<MeshRenderer>().sharedMaterial=font.material;
    }
    void CylinderPiece(Transform parent,string name,Vector3 position,Vector3 scale,string material,bool solid)
    {
        GameObject part=GameObject.CreatePrimitive(PrimitiveType.Cylinder);part.name=name;part.transform.SetParent(parent,false);
        part.transform.localPosition=position;part.transform.localScale=scale;part.GetComponent<Renderer>().sharedMaterial=materials[material];
        // A flattened capsule is not a valid tabletop collider. Use the actual
        // cylinder mesh so seating does not create invisible collision spheres.
        DestroyImmediate(part.GetComponent<Collider>());
        if(solid)part.AddComponent<MeshCollider>().sharedMesh=part.GetComponent<MeshFilter>().sharedMesh;
    }
    static Shape BenchSector(float inner,float outer,float middleDegrees)
    {
        const int segments=12;int n=segments+1;float[] vertices=new float[4*n];int[] indices=new int[segments*6];
        for(int j=0;j<n;j++)
        {
            float a=(middleDegrees+27f-54f*j/segments)*Mathf.Deg2Rad;
            vertices[2*j]=Mathf.Cos(a)*outer;vertices[2*j+1]=Mathf.Sin(a)*outer;
            int k=2*n-1-j;vertices[2*k]=Mathf.Cos(a)*inner;vertices[2*k+1]=Mathf.Sin(a)*inner;
        }
        for(int j=0;j<segments;j++)
        {
            int a=j,b=j+1,c=2*n-2-j,d=2*n-1-j,k=j*6;
            indices[k]=a;indices[k+1]=b;indices[k+2]=c;indices[k+3]=a;indices[k+4]=c;indices[k+5]=d;
        }
        return new Shape{v=vertices,t=indices,rings=new[]{new Ring{first=0,count=2*n}}};
    }
    void BuildPicnicTable(Transform parent,PicnicTable table,int index)
    {
        Transform furniture=Group("Round table and curved benches "+(index+1),parent);
        furniture.localPosition=new Vector3(table.x,0,table.z);furniture.localScale=Vector3.one*(table.radius/1.20f);
        CylinderPiece(furniture,"Round concrete tabletop",new Vector3(0,.72f,0),new Vector3(1.24f,.04f,1.24f),"Picnic concrete",colliders);
        CylinderPiece(furniture,"Table pedestal",new Vector3(0,.36f,0),new Vector3(.34f,.32f,.34f),"Picnic concrete",colliders);
        CylinderPiece(furniture,"Pedestal foot",new Vector3(0,.04f,0),new Vector3(.56f,.04f,.56f),"Picnic concrete",colliders);
        for(int seat=0;seat<4;seat++)
        {
            float angle=seat*90f;
            MeshObject(furniture,"Curved bench "+(seat+1),Extrude(BenchSector(.90f,1.20f,angle),.36f,p=>.45f),"Picnic concrete",$"F1_Picnic{index}_Seat{seat}",colliders);
            foreach(int side in new[]{-1,1})
            {
                float a=(angle+side*15)*Mathf.Deg2Rad;
                CylinderPiece(furniture,"Bench support",new Vector3(Mathf.Cos(a)*1.05f,.20f,Mathf.Sin(a)*1.05f),new Vector3(.09f,.16f,.09f),"Metal",colliders);
            }
            Vector3 start=Vector3.up*.15f,end=new Vector3(Mathf.Cos(angle*Mathf.Deg2Rad)*1.05f,.15f,Mathf.Sin(angle*Mathf.Deg2Rad)*1.05f);
            GameObject support=Box(furniture,"Low radial bench support",(start+end)/2,new Vector3(.05f,.05f,(end-start).magnitude),"Metal",colliders);support.transform.localRotation=Quaternion.LookRotation(end-start);
        }
    }
    void BuildPiano(Transform parent,float[] pos)
    {
        parent.localPosition=new Vector3(pos[0],0,pos[1]);
        // Keyboard and bench south of the tail: the seated player faces north (+X).
        Box(parent,"Baby grand body",new Vector3(.02f,.8f,0),new Vector3(1.7f,.24f,1.42f),"Piano",colliders);
        GameObject tail=GameObject.CreatePrimitive(PrimitiveType.Cylinder);tail.name="Rounded piano tail";tail.transform.SetParent(parent,false);tail.transform.localPosition=new Vector3(.75f,.8f,0);tail.transform.localScale=new Vector3(.75f,.12f,1.2f);tail.GetComponent<Renderer>().sharedMaterial=materials["Piano"];DestroyImmediate(tail.GetComponent<Collider>());if(colliders)tail.AddComponent<MeshCollider>().sharedMesh=tail.GetComponent<MeshFilter>().sharedMesh;
        foreach(float z in new[]{-.55f,.55f})Box(parent,"Piano leg",new Vector3(-.55f,.35f,z),new Vector3(.08f,.7f,.08f),"Piano",colliders);
        Box(parent,"Tail leg",new Vector3(.85f,.35f,0),new Vector3(.08f,.7f,.08f),"Piano",colliders);
        Box(parent,"Keyboard",new Vector3(-.93f,.76f,0),new Vector3(.25f,.04f,1.4f),"Ivory",false);
        for(int i=0;i<52;i++)
        {
            float z=-.69f+(i+.5f)*1.38f/52;Box(parent,"Key separation",new Vector3(-.94f,.786f,z),new Vector3(.24f,.003f,.0015f),"Piano",false);
            if(i<51&&i%7!=1&&i%7!=4)Box(parent,"Black key",new Vector3(-.88f,.8f,z+.69f/52),new Vector3(.13f,.025f,.015f),"Piano",false);
        }
        Box(parent,"Bench faces north",new Vector3(-1.5f,.45f,0),new Vector3(.4f,.12f,.8f),"Piano",colliders);
        foreach(float x in new[]{-1.65f,-1.35f})foreach(float z in new[]{-.28f,.28f})Box(parent,"Bench leg",new Vector3(x,.2f,z),new Vector3(.045f,.4f,.045f),"Piano",colliders);
    }
    Material PrepareReference(Floor f)
    {
        string path=Folder+"/Floor"+f.number+"Reference.png";
        byte[] bytes=Convert.FromBase64String(f.reference);
        if(!File.Exists(path)||!File.ReadAllBytes(path).SequenceEqual(bytes)){File.WriteAllBytes(path,bytes);AssetDatabase.ImportAsset(path,ImportAssetOptions.ForceUpdate);}
        TextureImporter importer=AssetImporter.GetAtPath(path) as TextureImporter;
        if(importer!=null && (importer.mipmapEnabled||importer.maxTextureSize<2048||importer.textureCompression!=TextureImporterCompression.Uncompressed))
        {importer.mipmapEnabled=false;importer.maxTextureSize=4096;importer.textureCompression=TextureImporterCompression.Uncompressed;importer.SaveAndReimport();}
        Texture2D texture=AssetDatabase.LoadAssetAtPath<Texture2D>(path);
        string matpath=Folder+"/Floor"+f.number+"Reference.mat";Material mat=AssetDatabase.LoadAssetAtPath<Material>(matpath);
        if(texture==null)throw new InvalidOperationException("Floor "+f.number+" source texture failed to import.");
        if(mat==null){Shader sh=Shader.Find("Universal Render Pipeline/Unlit")??Shader.Find("Unlit/Texture");if(sh==null)throw new InvalidOperationException("A reference texture shader is missing.");mat=new Material(sh);AssetDatabase.CreateAsset(mat,matpath);}
        mat.mainTexture=texture;if(mat.HasProperty("_BaseMap"))mat.SetTexture("_BaseMap",texture);if(mat.HasProperty("_BaseColor"))mat.SetColor("_BaseColor",Color.white);EditorUtility.SetDirty(mat);
        return mat;
    }
    void BuildReference(Transform level,Floor f)
    {
        if(!referenceMaterials.TryGetValue(f.number,out Material mat)||mat==null)
            throw new InvalidOperationException("Floor "+f.number+" source reference was not prepared.");
        Transform t=Group("Reference overlay",level);
        Mesh mesh=Surface(f.refMesh,.035f);var uv=new Vector2[f.refUV.Length/2];for(int i=0;i<uv.Length;i++)uv[i]=new Vector2(f.refUV[i*2],f.refUV[i*2+1]);mesh.uv=uv;
        t.gameObject.AddComponent<MeshFilter>().sharedMesh=Persist(mesh,"Floor"+f.number+"Reference");t.gameObject.AddComponent<MeshRenderer>().sharedMaterial=mat;t.gameObject.SetActive(false);
    }
    void BuildRoofs(Transform building)
    {
        Transform roofs=Group("Roofs",building);
        foreach(Roof roof in Data().roofs)
        {
            Transform cap=Group(roof.name,roofs);cap.localPosition=Vector3.up*(roof.aboveFloor*floorHeight);
            string key="RoofAbove"+roof.aboveFloor;
            MeshObject(cap,"Structural roof slab",Extrude(roof.slab,-roofSlabDepth,p=>0),"Roof concrete",key+"_Slab",colliders);
            if(roof.membrane.t.Length>0)MeshObject(cap,"Roof membrane",Surface(roof.membrane,.006f),"Roof membrane",key+"_Membrane",false);
            if(roof.zone.t.Length>0)MeshObject(cap,"Plan-shaded roof surface",Surface(roof.zone,.006f),"Roof shaded zone",key+"_Zone",false);
            float h=roofParapetHeight*roof.parapetScale;
            if(roof.parapet.t.Length>0)
            {
                MeshObject(cap,"Low perimeter parapet",Extrude(roof.parapet,0,p=>h),"Facade white",key+"_Parapet",colliders);
                MeshObject(cap,"Parapet coping",Extrude(roof.coping,h,p=>h+.055f),"Roof coping",key+"_Coping",colliders);
            }
        }
        roofs.gameObject.SetActive(roofsVisible);
    }
    void BuildSite(Transform site)
    {
        // Grade is not surveyed. This surface meets the real Floor 2 north entrances.
        float shift=Data().northSiteShiftX;
        Box(site,"Raised north ground",new Vector3(112+shift,floorHeight/2-.1f,17),new Vector3(8,floorHeight+.2f,43),"Terrain",colliders);
        Box(site,"Lower west ground and exterior room approaches",new Vector3(30.25f,-.17f,19),new Vector3(64.5f,.3f,42),"Terrain",colliders);
        Box(site,"North walkway",new Vector3(108.4f+shift,floorHeight-.08f,17),new Vector3(3,.16f,43),"Concrete",colliders);
        Box(site,"Covered entrance apron",new Vector3(105.8f+shift,floorHeight-.08f,15.6f),new Vector3(4,.16f,10),"Concrete",colliders);
    }
    static Transform Group(string name,Transform parent)
    {Transform t=new GameObject(name).transform;t.SetParent(parent,false);return t;}
    GameObject Box(Transform parent,string name,Vector3 position,Vector3 size,string material,bool solid)
    {
        GameObject go=GameObject.CreatePrimitive(PrimitiveType.Cube);go.name=name;go.transform.SetParent(parent,false);go.transform.localPosition=position;go.transform.localScale=size;go.GetComponent<Renderer>().sharedMaterial=materials[material];if(!solid)DestroyImmediate(go.GetComponent<Collider>());return go;
    }
    void Beam(Transform parent,Vector3 a,Vector3 b,float width)
    {Vector3 d=b-a;if(d.magnitude<.001f)return;GameObject go=Box(parent,"Red handrail",(a+b)/2,new Vector3(width,d.magnitude,width),"Rail",colliders);go.transform.localRotation=Quaternion.FromToRotation(Vector3.up,d.normalized);}
    static void Label(Transform parent,string text,Vector3 position)
    {
        Transform t=Group(text,parent);t.localPosition=position;t.localRotation=Quaternion.Euler(90,0,0);TextMesh label=t.gameObject.AddComponent<TextMesh>();label.text=text;label.fontSize=48;label.characterSize=.075f;label.anchor=TextAnchor.MiddleCenter;label.color=Color.black;
        Font font=Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");label.font=font;t.GetComponent<MeshRenderer>().sharedMaterial=font.material;
    }
    static void EnsureFolders()
    {if(!AssetDatabase.IsValidFolder(AssetRoot))AssetDatabase.CreateFolder("Assets","EngineeringBuildingGenerated");if(!AssetDatabase.IsValidFolder(Folder))AssetDatabase.CreateFolder(AssetRoot,"V67");}
    void EnsureMaterials()
    {
        materials.Clear();Mat("Wall",new Color(.85f,.86f,.86f));Mat("Corridor",new Color(.91f,.91f,.9f));
        Mat("Lecture",new Color(.8f,.6f,.8f));Mat("Imagination",new Color(1,.6f,0));Mat("Realization",new Color(1,1,0));
        Mat("Department",new Color(.6f,1,.4f));Mat("Office",new Color(.6f,1,1));Mat("Public",new Color(.96f,.588f,.596f));Mat("Operations",new Color(.875f,.835f,.839f));
        Mat("Stair",new Color(.22f,.23f,.24f));Mat("Nosing",new Color(.95f,.85f,.08f));Mat("Rail",new Color(.65f,.06f,.04f));Mat("Concrete",new Color(.63f,.64f,.63f));Mat("Terrain",new Color(.26f,.4f,.2f));
        Mat("Metal",new Color(.4f,.45f,.48f));Mat("Glass",new Color(.4f,.7f,.8f,.28f));Mat("Piano",new Color(.055f,.035f,.025f));Mat("Ivory",new Color(.97f,.95f,.88f));
        Mat("Facade panel",new Color(.74f,.70f,.65f));Mat("Facade white",new Color(.90f,.90f,.86f));
        Mat("Wing brick panel",new Color(.48f,.27f,.21f));Mat("Window silver",new Color(.52f,.57f,.58f));Mat("Window brown",new Color(.38f,.25f,.20f));
        Mat("Window glass",new Color(.26f,.36f,.40f,.58f));Mat("Shade detail",new Color(.70f,.72f,.69f));Mat("Panel joint",new Color(.62f,.59f,.55f));
        Mat("Roof concrete",new Color(.69f,.70f,.68f));Mat("Roof membrane",new Color(.50f,.53f,.52f));
        Mat("Roof coping",new Color(.78f,.80f,.78f));Mat("Roof shaded zone",new Color(.65f,.52f,.36f));
        Mat("Picnic concrete",new Color(.62f,.64f,.60f));Mat("Vending blue",new Color(.10f,.23f,.48f));Mat("Vending red",new Color(.62f,.11f,.10f));
        foreach(string name in new[]{"Glass","Window glass"})
        {
            Material glass=materials[name];if(glass.HasProperty("_Surface"))glass.SetFloat("_Surface",1);if(glass.HasProperty("_Mode"))glass.SetFloat("_Mode",3);
            if(glass.HasProperty("_SrcBlend"))glass.SetFloat("_SrcBlend",(float)BlendMode.SrcAlpha);if(glass.HasProperty("_DstBlend"))glass.SetFloat("_DstBlend",(float)BlendMode.OneMinusSrcAlpha);if(glass.HasProperty("_ZWrite"))glass.SetFloat("_ZWrite",0);
            if(glass.HasProperty("_Smoothness"))glass.SetFloat("_Smoothness",.6f);if(glass.HasProperty("_Glossiness"))glass.SetFloat("_Glossiness",.6f);
            glass.EnableKeyword("_SURFACE_TYPE_TRANSPARENT");glass.EnableKeyword("_ALPHABLEND_ON");glass.SetOverrideTag("RenderType","Transparent");glass.renderQueue=3000;glass.SetShaderPassEnabled("ShadowCaster",false);EditorUtility.SetDirty(glass);
        }
    }
    void Mat(string name,Color color)
    {
        string path=Folder+"/"+name+".mat";Material m=AssetDatabase.LoadAssetAtPath<Material>(path);
        if(m==null){Shader shader=Shader.Find("Universal Render Pipeline/Lit")??Shader.Find("Standard");if(shader==null)throw new InvalidOperationException("URP/Lit or Standard shader required.");m=new Material(shader){name=name};m.color=color;if(m.HasProperty("_BaseColor"))m.SetColor("_BaseColor",color);AssetDatabase.CreateAsset(m,path);}materials[name]=m;
    }
    static GameObject FindBuilding()
    {
        Scene scene=SceneManager.GetActiveScene();
        return scene.IsValid()&&scene.isLoaded?scene.GetRootGameObjects().FirstOrDefault(g=>g.name==RootName):null;
    }
    static Transform FloorRoot(int n){GameObject root=FindBuilding();return root!=null?root.transform.Find("Floor "+n):null;}
    void DrawFloor(int n)
    {
        Transform t=FloorRoot(n);
        using(new EditorGUI.DisabledScope(t==null))
        using(new EditorGUILayout.HorizontalScope())
        {
            EditorGUILayout.LabelField("Floor "+n,GUILayout.Width(48));bool active=t!=null&&t.gameObject.activeSelf;
            bool next=EditorGUILayout.ToggleLeft("Active",active,GUILayout.Width(65));
            if(t!=null&&next!=active){RecordSceneChange(t.gameObject,"Floor visibility");t.gameObject.SetActive(next);Dirty();}
            Transform reference=t!=null?t.Find("Reference overlay"):null;
            bool rendered=t!=null&&t.GetComponentsInChildren<Renderer>(true).Any(r=>r.enabled&&r.GetComponent<TextMesh>()==null&&(reference==null||!r.transform.IsChildOf(reference)));
            bool render=EditorGUILayout.ToggleLeft("Render",rendered,GUILayout.Width(70));if(t!=null&&render!=rendered)Render(t,render);
            Transform sheet=t!=null?t.Find("Reference overlay"):null;bool shown=sheet!=null&&sheet.gameObject.activeSelf;
            bool show=EditorGUILayout.ToggleLeft("Reference",shown,GUILayout.Width(85));
            if(sheet!=null&&show!=shown){RecordSceneChange(sheet.gameObject,"Source reference visibility");sheet.gameObject.SetActive(show);Renderer r=sheet.GetComponent<Renderer>();if(r!=null)r.enabled=show;Dirty();}
            if(GUILayout.Button("Top",GUILayout.Width(40))&&t!=null){Selection.activeGameObject=t.gameObject;SceneView view=SceneView.lastActiveSceneView;if(view!=null){view.rotation=Quaternion.Euler(90,0,0);view.orthographic=true;view.FrameSelected();}}
            if(GUILayout.Button("Focus",GUILayout.Width(48))&&t!=null){Selection.activeGameObject=t.gameObject;SceneView.lastActiveSceneView?.FrameSelected();}
            using(new EditorGUI.DisabledScope(IsPlaySession||working||queuedOperation!=0))
                if(GUILayout.Button("Despawn",GUILayout.Width(65))&&t!=null)QueueOperation(100+n);
        }
    }
    void DespawnFloor(int n)
    {
        if(IsPlaySession){status="Stop Play Mode before despawning floors.";Repaint();return;}
        Transform floor=FloorRoot(n);if(floor==null)return;
        GameObject root=FindBuilding();Transform connections=root!=null?root.transform.Find("Stair connections/From Floor "+n):null;
        Undo.IncrementCurrentGroup();int group=Undo.GetCurrentGroup();Undo.SetCurrentGroupName("Despawn Floor "+n);
        if(connections!=null)Undo.DestroyObjectImmediate(connections.gameObject);
        Undo.DestroyObjectImmediate(floor.gameObject);Undo.CollapseUndoOperations(group);
        SyncLabels();Dirty();status="Floor "+n+" despawned. Undo or regenerate to restore it.";
    }
    void DrawRoofs()
    {
        EditorGUILayout.Space();EditorGUILayout.LabelField("Roofs",EditorStyles.boldLabel);
        GameObject building=FindBuilding();Transform root=building!=null?building.transform.Find("Roofs"):null;
        bool visible=EditorGUILayout.Toggle("Roofs visible",roofsVisible);
        if(visible!=roofsVisible)
        {
            roofsVisible=visible;
            if(root!=null){RecordSceneChange(root.gameObject,"Roof visibility");root.gameObject.SetActive(visible);Dirty();}
        }
        Roof[] definitions=runtimePlans!=null&&runtimePlans.roofs!=null?runtimePlans.roofs:new Roof[0];
        using(new EditorGUI.DisabledScope(root==null))foreach(Roof roof in definitions)
        using(new EditorGUILayout.HorizontalScope())
        {
            Transform part=root!=null?root.Find(roof.name):null;
            EditorGUILayout.LabelField(roof.name,GUILayout.MinWidth(200));
            bool active=part!=null&&part.gameObject.activeSelf;
            bool next=EditorGUILayout.ToggleLeft("Active",active,GUILayout.Width(65));
            if(part!=null&&next!=active){RecordSceneChange(part.gameObject,"Roof active");part.gameObject.SetActive(next);Dirty();}
            bool rendered=part!=null&&part.GetComponentsInChildren<Renderer>(true).Any(r=>r.enabled);
            bool render=EditorGUILayout.ToggleLeft("Render",rendered,GUILayout.Width(70));
            if(part!=null&&render!=rendered)Render(part,render);
        }
    }
    void DrawSite()
    {
        GameObject root=FindBuilding();
        Transform stairs=root!=null?root.transform.Find("Stair connections"):null;
        using(new EditorGUI.DisabledScope(stairs==null))
        {bool active=stairs!=null&&stairs.gameObject.activeSelf;bool next=EditorGUILayout.Toggle("Stair connections active",active);if(stairs!=null&&next!=active){RecordSceneChange(stairs.gameObject,"Stair connections");stairs.gameObject.SetActive(next);Dirty();}}
        Transform t=root!=null?root.transform.Find("Site"):null;using(new EditorGUI.DisabledScope(t==null))
        {bool active=t!=null&&t.gameObject.activeSelf;bool next=EditorGUILayout.Toggle("Site active",active);if(t!=null&&next!=active){RecordSceneChange(t.gameObject,"Site active");t.gameObject.SetActive(next);Dirty();}}
    }
    static void Render(Transform t,bool visible)
    {foreach(Renderer r in t.GetComponentsInChildren<Renderer>(true)){RecordSceneChange(r,"Floor renderers");r.enabled=visible;}Dirty();}
    void Preset(int n)
    {
        for(int i=1;i<=FloorCount;i++)
        {Transform t=FloorRoot(i);if(t==null)continue;RecordSceneChange(t.gameObject,"Inspect floors");t.gameObject.SetActive(n==0||i==n);Render(t,true);}
        GameObject root=FindBuilding();Transform connections=root!=null?root.transform.Find("Stair connections"):null;
        if(connections!=null){RecordSceneChange(connections.gameObject,"Inspect connections");connections.gameObject.SetActive(true);for(int i=1;i<=FloorCount;i++){Transform child=connections.Find("From Floor "+i);if(child==null)continue;RecordSceneChange(child.gameObject,"Inspect connection");child.gameObject.SetActive(n==0||i==n||i==n-1);}}
        Transform site=root!=null?root.transform.Find("Site"):null;if(site!=null){RecordSceneChange(site.gameObject,"Inspect site");site.gameObject.SetActive(n==0||n==2);}SyncLabels();Dirty();
        Transform roofs=root!=null?root.transform.Find("Roofs"):null;
        if(roofs!=null)
        {
            RecordSceneChange(roofs.gameObject,"Inspect roofs");roofs.gameObject.SetActive(roofsVisible);
            Roof[] definitions=runtimePlans!=null&&runtimePlans.roofs!=null?runtimePlans.roofs:new Roof[0];
            foreach(Roof roof in definitions)
            {
                Transform cap=roofs.Find(roof.name);if(cap==null)continue;
                RecordSceneChange(cap.gameObject,"Inspect roofs");cap.gameObject.SetActive(n==0||roof.aboveFloor==n-1);
                Render(cap,true);
            }
        }
        SyncLabels();Dirty();
    }
    void SyncLabels()
    {
        int highest=0;for(int i=1;i<=FloorCount;i++){Transform t=FloorRoot(i);if(t!=null&&t.gameObject.activeInHierarchy&&t.GetComponentsInChildren<MeshRenderer>(true).Any(r=>r.enabled&&r.GetComponent<TextMesh>()==null))highest=i;}
        for(int i=1;i<=FloorCount;i++){Transform t=FloorRoot(i);Transform labels=t!=null?t.Find("Room labels"):null;if(labels!=null&&labels.gameObject.activeSelf!=(roomLabels&&highest==i&&(t.Find("Reference overlay")==null||!t.Find("Reference overlay").gameObject.activeSelf)))labels.gameObject.SetActive(roomLabels&&highest==i&&(t.Find("Reference overlay")==null||!t.Find("Reference overlay").gameObject.activeSelf));}
    }
    static void Dirty()
    {
        // Visibility controls are also useful during Play Mode. Runtime scene
        // changes must not call the edit-only MarkSceneDirty API.
        if(!IsPlaySession)
        {
            Scene scene=SceneManager.GetActiveScene();
            if(scene.IsValid()&&scene.isLoaded)EditorSceneManager.MarkSceneDirty(scene);
        }
        SceneView.RepaintAll();
    }
